import { fanfanloI18n, IFrameReactContainer, useTranslation, Log } from "@fanfanlo";
import { Box, Button, Stack, TextareaAutosize, Typography, CircularProgress, Alert } from "@mui/material";
import { ScriptEditorContextLoader } from "@src/components/script-editor/data/context";
import { loadScrptEditorData } from "@src/components/script-editor/data/script-editor.data.intf";
import { marketHtmlUtils } from "@src/markets/market-html-utils";
import { useState, useCallback, useRef, useEffect } from "react";
import { useDroidDocsScripts } from "./useDroidDocsScripts";
import type { DifficultyLevel } from "@src/services/droid-docs-api";
import { autoWebViewJs } from "@droid/android";

const fileLog = new Log(false, 'ScriptEditorContent_f');

export function ScriptEditorContent({
    ns,
    initialCategory,
    initialName,
    initialScript
}:{
    ns?: string;
    initialCategory?: DifficultyLevel;
    initialName?: string;
    initialScript?: boolean;
}) {

    const lang = fanfanloI18n.language || 'en'
    // 使用 droid-docs API 获取脚本数据
    const {
        examplesMap,
        selectedLevel,
        selectedScript,
        scriptContent,
        isLoadingMap,
        isLoadingScript,
        mapError,
        scriptError,
        setSelectedLevel,
        selectScript,
        updateScriptContent
    } = useDroidDocsScripts(lang);

    console.log('[ScriptEditorContent] useDroidDocsScripts 初始化完成', {
        examplesMapLoaded: !!examplesMap,
        selectedLevel,
        selectedScriptName: selectedScript?.name,
        scriptContentLength: scriptContent.length,
        isLoadingMap,
        isLoadingScript
    });

    // 运行脚本状态
    const [runScript, setRunScript] = useState('')
    console.log('[ScriptEditorContent] 初始化 runScript: 空字符串');

    const { t } = useTranslation(`homepage/components/script-editor/content/content`)

    // 如果提供了初始参数，自动选择并加载脚本
    useEffect(() => {
        fileLog.log('ScriptEditorContent', `InitialParams effect triggered: initialCategory=${initialCategory}, initialName=${initialName}, examplesMapLoaded=${!!examplesMap}`);

        if (!initialCategory || !initialName || !examplesMap) {
            if (initialCategory && initialName) {
                fileLog.log('ScriptEditorContent', 'Waiting for examplesMap to load');
            }
            return;
        }

        fileLog.log('ScriptEditorContent', `Initializing with: category=${initialCategory}, name=${initialName}, script=${initialScript}`);

        const levelScripts = examplesMap[initialCategory];
        if (!levelScripts) {
            fileLog.error('ScriptEditorContent', `Category not found: ${initialCategory}`);
            return;
        }

        // 按 path 查找脚本，而不是按 name，因为 name 是 i18n 翻译后的名称
        // path 格式: "category/script-name"，例如: "beginner/vibrate"
        const targetScript = levelScripts.find(s => s.path === `${initialCategory}/${initialName}`);
        if (!targetScript) {
            fileLog.error('ScriptEditorContent', `Script not found: ${initialCategory}/${initialName}`);
            fileLog.log('ScriptEditorContent', `Available scripts in ${initialCategory}:`, levelScripts.map(s => ({ path: s.path, name: s.name })));
            return;
        }

        fileLog.log('ScriptEditorContent', `Found target script: ${targetScript.name}`);
        // 不调用 setSelectedLevel，因为它会自动选择该级别的第一个脚本
        // 直接调用 selectScript 来选择指定的脚本
        selectScript(targetScript);

        if (initialScript === false) {
            fileLog.log('ScriptEditorContent', 'initialScript is false, clearing content');
            updateScriptContent('');
        }
    }, [initialCategory, initialName, initialScript, examplesMap, setSelectedLevel, selectScript, updateScriptContent]);

    // 使用 useRef 标记是否已加载，防止重复执行 loadScrptEditorData
    const hasLoadedRef = useRef(false);

    // 创建稳定的加载函数引用，使用 useCallback 只在 ns 改变时重新创建
    const loadData = useCallback(async () => {
        console.log(`[ScriptEditorContent] loadData 函数被调用，hasLoaded=${hasLoadedRef.current}`);

        // 防止重复加载：如果已加载过，直接返回空 Promise
        if (hasLoadedRef.current) {
            console.log(`[ScriptEditorContent] 数据已加载过，跳过重新加载`);
            return Promise.resolve(null);
        }

        console.log(`[ScriptEditorContent] 开始加载数据，ns=${ns}`);
        hasLoadedRef.current = true;

        try {
            const result = await loadScrptEditorData(ns);
            console.log(`[ScriptEditorContent] 数据加载完成`, result);
            return result;
        } catch (error) {
            console.error(`[ScriptEditorContent] 数据加载失败`, error);
            hasLoadedRef.current = false;  // 加载失败，允许重试
            throw error;
        }
    }, [ns]);

    // 处理难度级别变更
    const handleLevelChange = (level: DifficultyLevel) => {
        console.log(`[ScriptEditorContent] 切换难度级别为: ${level}`);
        setSelectedLevel(level);
    }

    // 处理脚本选择
    const handleScriptChange = async (scriptPath: string) => {
        console.log(`[ScriptEditorContent] 选择脚本: ${scriptPath}`);

        if (!examplesMap) {
            console.error('[ScriptEditorContent] examplesMap 未加载');
            return;
        }

        // 从所有级别中查找脚本
        let foundScript = null;
        for (const level of ['beginner', 'intermediate', 'advanced'] as const) {
            const scripts = examplesMap[level];
            console.log(`[ScriptEditorContent] 在 ${level} 级别中查找脚本`);

            foundScript = scripts.find(s => s.path === scriptPath);
            if (foundScript) {
                console.log(`[ScriptEditorContent] 在 ${level} 级别找到脚本: ${foundScript.name}`);
                break;
            }
        }

        if (foundScript) {
            console.log(`[ScriptEditorContent] 开始加载脚本内容`);
            await selectScript(foundScript);
        } else {
            console.error('[ScriptEditorContent] 未找到脚本:', scriptPath);
        }
    }

    function onRunClick(){
        console.log(`[ScriptEditorContent] 执行脚本, 脚本名称: ${selectedScript?.name}`);
        const isLoadHtml = false;
        if(isLoadHtml){
            setRunScript('')
            setTimeout(()=>setRunScript(scriptContent), 100 * 3)
        }else{
            autoWebViewJs.callScript(scriptContent)
        }
    }

    // 获取当前级别的脚本列表
    const currentLevelScripts = examplesMap ? examplesMap[selectedLevel] : [];
    console.log(`[ScriptEditorContent] 当前级别 (${selectedLevel}) 有 ${currentLevelScripts?.length || 0} 个脚本`);

    console.log('rendering ScriptEditorContent')
    return (
        <>
        <ScriptEditorContextLoader value={loadData}>
            <Box>
                <Typography variant="h5">{t(ns ? 'ScriptEditorContent.name.editScript' : 'ScriptEditorContent.name.createScript')}</Typography>
                <Stack direction={"column"} spacing={2}>
                    {/* 加载状态 */}
                    {isLoadingMap && (
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <CircularProgress size={24} />
                            <Typography variant="body2">{t('ScriptEditorContent.loading')}</Typography>
                        </Box>
                    )}

                    {/* 错误显示 */}
                    {mapError && (
                        <Alert severity="error">
                            {t('ScriptEditorContent.mapError')}: {mapError.message}
                        </Alert>
                    )}

                    {scriptError && (
                        <Alert severity="error">
                            {t('ScriptEditorContent.scriptError')}: {scriptError.message}
                        </Alert>
                    )}

                    {/* 难度级别选择器 */}
                    {examplesMap && (
                        <Box>
                            <Stack direction={"row"} spacing={1} style={{marginBottom: '12px', alignItems: 'center', flexWrap: 'wrap'}}>
                                <Typography variant="body2" style={{fontWeight: 500}}>{t('ScriptEditorContent.difficulty')}:</Typography>
                                {(['beginner', 'intermediate', 'advanced'] as const).map((level) => (
                                    <Button
                                        key={level}
                                        variant={selectedLevel === level ? 'contained' : 'outlined'}
                                        size="small"
                                        onClick={() => handleLevelChange(level)}
                                    >
                                        {t(`ScriptEditorContent.difficultyLevels.${level}`)}
                                        {` (${examplesMap[level].length})`}
                                    </Button>
                                ))}
                            </Stack>
                        </Box>
                    )}

                    {/* 脚本选择器 */}
                    {examplesMap && currentLevelScripts && currentLevelScripts.length > 0 && (
                        <Box>
                            <Stack direction={"row"} spacing={1} style={{marginBottom: '12px', alignItems: 'center'}}>
                                <Typography variant="body2" style={{fontWeight: 500}}>{t('ScriptEditorContent.selectScript')}:</Typography>
                                <select
                                    value={selectedScript?.path || ''}
                                    onChange={(e) => handleScriptChange(e.target.value)}
                                    disabled={isLoadingScript}
                                    style={{padding: '8px 12px', borderRadius: '4px', border: '1px solid #ccc'}}
                                >
                                    <option value="">{t('ScriptEditorContent.selectScriptPlaceholder')}</option>
                                    {currentLevelScripts.map((script) => (
                                        <option key={script.path} value={script.path}>
                                            {script.name} - {script.desc}
                                        </option>
                                    ))}
                                </select>
                                {isLoadingScript && <CircularProgress size={20} />}
                            </Stack>
                        </Box>
                    )}

                    {/* 控制按钮 */}
                    <Box>
                        {/* <Button>examples2</Button>
                        <Button>docs</Button> */}
                        <Button onClick={onRunClick} disabled={!selectedScript || isLoadingScript}>{t('ScriptEditorContent.run')}</Button>
                    </Box>

                    {/* 脚本编辑器 */}
                    <Box>
                        <TextareaAutosize
                        value={scriptContent}
                        onChange={(e)=>updateScriptContent(e.target.value)}
                         style={{width:"100%",minHeight:"200px"}} />
                    </Box>

                    {/* 脚本执行容器 */}
                    <Box>
                        {runScript && <IFrameReactContainer
                        content={runScript}
                        urlAsContent={true}
                        htmlBuilder={marketHtmlUtils.mergeHtml}
                        />}
                    </Box>
                </Stack>
            </Box>
        </ScriptEditorContextLoader>
        </>
    )
}
